def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    base = counts.most_common(1)[0][0]
    sep = Counter(v for row in grid for v in row if v != base).most_common(1)[0][0]

    row_lines = [r for r in range(h) if sum(v == base for v in grid[r]) < w / 2]
    col_lines = [c for c in range(w) if sum(grid[r][c] == base for r in range(h)) < h / 2]

    def marked(r, c):
        return grid[r][c] != base and grid[r][c] != sep

    row_lines = [r for r in row_lines if any(marked(r, c) for c in col_lines)]
    col_lines = [c for c in col_lines if any(marked(r, c) for r in row_lines)]

    return [
        [
            grid[r1][c1] if grid[r1][c1] == grid[r1][c2] == grid[r2][c1] == grid[r2][c2]
            and marked(r1, c1) else base
            for c1, c2 in zip(col_lines, col_lines[1:])
        ]
        for r1, r2 in zip(row_lines, row_lines[1:])
    ]
